// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { AlertTriangleIcon, BracesIcon, RefreshCwIcon, XCircleIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  BEFORE,
  CAPTIONS,
  ERRORS,
  H1,
  IMAGES_TAB,
  ISSUES_TAB,
  MISSING_ALT,
  PAGE,
  PAGE_URL,
  RING,
  TABS,
  TITLE,
  TITLE_MAX,
  WARNINGS,
  type Issue,
} from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, count, wait, cursorOut }) => {
  const strip = q('tabstrip')
  const shift = Math.max(
    0,
    strip.scrollWidth - (strip.parentElement?.clientWidth ?? strip.scrollWidth),
  )
  const tab = (index: number) => {
    tl.to(
      qa('tab'),
      { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`tab-${index}`),
      { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)', duration: 0.15 },
      '<',
    )
  }
  const view = (name: string) => {
    tl.to(qa('view'), { opacity: 0, duration: 0.15 }, '<')
    tl.fromTo(
      q(`view-${name}`),
      { opacity: 0, y: 6 },
      { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out', immediateRender: false },
      '<0.1',
    )
  }

  step(0)
  tl.fromTo(
    qa('skel'),
    { opacity: 0.35 },
    { opacity: 0.8, duration: 0.35, repeat: 2, yoyo: true, stagger: 0.05, immediateRender: false },
    0.1,
  )
  tl.to(q('skeleton'), { opacity: 0, duration: 0.2 })
  tl.fromTo(
    q('report'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  tl.fromTo(
    q('ring'),
    { strokeDashoffset: RING },
    {
      strokeDashoffset: RING * (1 - BEFORE.score / 100),
      duration: 1,
      ease: 'power2.out',
      immediateRender: false,
    },
    '<0.15',
  )
  count('score', BEFORE.score, { at: '<', duration: 1 })
  count('score-badge', BEFORE.score, { at: '<', duration: 1, suffix: '/100' })
  tl.fromTo(
    q('issue-badge'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2.5)', immediateRender: false },
    '>-0.1',
  )
  tl.fromTo(
    qa('overview-row'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.07, immediateRender: false },
    '<',
  )
  move('title-row', { at: '+=0.2', ax: 0.75 })
  tl.fromTo(
    q('title-len'),
    { scale: 1 },
    { scale: 1.2, duration: 0.18, yoyo: true, repeat: 1, immediateRender: false },
    '>-0.05',
  )

  step(1, '+=0.6')
  tl.to(strip, { x: -shift, duration: 0.5, ease: 'power2.inOut' }, '<')
  move(`tab-${ISSUES_TAB}`, { dx: -shift, at: '<0.2' })
  click(`tab-${ISSUES_TAB}`)
  tab(ISSUES_TAB)
  view('issues')
  tl.fromTo(
    qa('issue'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.1, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  move('issue-1', { at: '+=0.3', ax: 0.3 })

  step(2, '+=0.8')
  move(`tab-${IMAGES_TAB}`, { dx: -shift })
  click(`tab-${IMAGES_TAB}`)
  tab(IMAGES_TAB)
  view('images')
  move('highlight', { at: '+=0.3' })
  click('highlight')
  tl.fromTo(
    q('outsole'),
    { outlineColor: 'rgba(245,158,11,0)', backgroundColor: 'rgba(245,158,11,0)' },
    {
      outlineColor: 'rgba(245,158,11,1)',
      backgroundColor: 'rgba(245,158,11,0.12)',
      duration: 0.3,
      immediateRender: false,
    },
    '<0.1',
  )
  tl.fromTo(
    q('outsole-shade'),
    { opacity: 0 },
    { opacity: 1, duration: 0.3, immediateRender: false },
    '<',
  )
  move('outsole', { at: '+=0.3' })
  cursorOut('+=0.8')
  final()
  wait(1.4)

  tl.set(
    [q('report'), q('issue-badge'), q('outsole-shade'), ...qa('overview-row')],
    { opacity: 0 },
    0,
  )
  tl.set(q('skeleton'), { opacity: 1 }, 0)
  tl.set(strip, { x: 0 }, 0)
  tl.set(
    q('outsole'),
    { outlineColor: 'rgba(245,158,11,0)', backgroundColor: 'rgba(245,158,11,0)' },
    0,
  )
}

