function Stat({ label, value, warn }: { label: string; value: number | string; warn?: boolean }) {
  return (
    <span
      className={`rounded-md border px-1 py-1 text-center ${warn ? 'border-amber-400/40 bg-amber-400/5' : 'border-line bg-ink/[0.03]'}`}
    >
      <span className="block text-[11px] font-semibold tabular-nums text-ink">{value}</span>
      <span className="block text-[7.5px] text-muted">{label}</span>
    </span>
  )
}

function Pill({ children }: { children: string }) {
  return (
    <span className="rounded-full border border-emerald-400/40 bg-emerald-400/5 px-1.5 py-px text-[7.5px] text-emerald-300">
      {children}
    </span>
  )
}

function MetaRow({
  label,
  value,
  badge,
  d,
}: {
  label: string
  value: string
  badge?: string
  d?: string
}) {
  return (
    <span
      data-d={`overview-row ${d ?? ''}`}
      className="block rounded-md border border-line bg-ink/[0.03] px-2 py-1 opacity-0"
    >
      <span className="flex items-center gap-1">
        <span className="text-[7px] font-medium uppercase tracking-wide text-muted">{label}</span>
        {badge ? (
          <span
            data-d="title-len"
            className="rounded border border-amber-400/50 px-1 text-[7px] text-amber-300"
          >
            {badge}
          </span>
        ) : null}
      </span>
      <span className="mt-0.5 block truncate text-[8.5px] text-ink">{value}</span>
    </span>
  )
}

function IssueRow({ issue, index }: { issue: Issue; index: number }) {
  const error = issue.severity === 'error'
  const Icon = error ? XCircleIcon : AlertTriangleIcon
  return (
    <span
      data-d={`issue issue-${index}`}
      className={`flex items-start gap-1.5 rounded-md border border-l-2 border-line bg-ink/[0.03] px-1.5 py-1 opacity-0 ${error ? 'border-l-rose-500/80' : 'border-l-amber-400/80'}`}
    >
      <Icon className={`mt-px size-2.5 shrink-0 ${error ? 'text-rose-400' : 'text-amber-300'}`} />
      <span className="min-w-0">
        <span className="block text-[8.5px] leading-snug text-ink">{issue.message}</span>
        {issue.fix ? (
          <span className="block text-[7.5px] leading-snug text-muted">{issue.fix}</span>
        ) : null}
      </span>
    </span>
  )
}

